/**
 * Perkecil foto di perangkat sebelum diunggah — satu-satunya kompresi foto portal.
 *
 * Foto kamera HP 3–12 MB; di uplink seluler pengirimannya bisa 10–20 detik per
 * foto. Sisi terpanjang diturunkan ke MAX_SISI lalu di-encode ke JPEG, sehingga
 * yang dikirim tinggal ratusan KB. Bila `maxBytes` diberikan, kualitas lalu
 * resolusi diturunkan bertahap sampai ukurannya masuk.
 *
 * Resolve File hasil kompres, atau:
 * - file asli bila tidak perlu diperkecil dan JPEG-nya tidak lebih hemat, atau
 *   browser tidak bisa membacanya (mis. HEIC di Chrome) sementara ukurannya masuk;
 * - null bila `maxBytes` diberikan dan tetap tidak bisa dipenuhi.
 */
// Samakan dengan MAX_LONG_EDGE_PX di data_pengajuan/foto_pengajuan.py dan
// juragan.photo di Desk (photo_upload.bundle.js).
export const MAX_SISI = 2400
const KUALITAS = [0.85, 0.75, 0.65, 0.55]
const SKALA_MINIMUM = 0.25

function bacaGambar(url) {
	return new Promise((resolve, reject) => {
		const img = new Image()
		img.onload = () => resolve(img)
		img.onerror = () => reject(new Error('Foto tidak bisa dibaca browser.'))
		img.src = url
	})
}

function keJpeg(canvas, kualitas) {
	return new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', kualitas))
}

export async function kompresFoto(file, maxBytes = 0) {
	if (!file) return null
	const masuk = !maxBytes || file.size <= maxBytes
	const url = URL.createObjectURL(file)
	try {
		let gambar
		try {
			// <img> memutar piksel sesuai EXIF Orientation (image-orientation:
			// from-image adalah default browser modern), jadi foto potret tidak miring.
			gambar = await bacaGambar(url)
		} catch {
			return masuk ? file : null
		}

		const nama = (file.name || 'foto').replace(/\.[^.]+$/, '') + '.jpg'
		const sisi = Math.max(gambar.naturalWidth, gambar.naturalHeight)
		let skala = Math.min(1, MAX_SISI / sisi)
		while (skala >= SKALA_MINIMUM) {
			const canvas = document.createElement('canvas')
			canvas.width = Math.max(1, Math.round(gambar.naturalWidth * skala))
			canvas.height = Math.max(1, Math.round(gambar.naturalHeight * skala))
			const ctx = canvas.getContext('2d')
			ctx.fillStyle = '#fff' // PNG transparan → latar putih, sama seperti server
			ctx.fillRect(0, 0, canvas.width, canvas.height)
			ctx.drawImage(gambar, 0, 0, canvas.width, canvas.height)
			for (const q of maxBytes ? KUALITAS : KUALITAS.slice(0, 1)) {
				const blob = await keJpeg(canvas, q)
				if (!blob) continue
				if (skala === 1 && blob.size >= file.size && masuk) return file
				if (!maxBytes || blob.size <= maxBytes) {
					return new File([blob], nama, { type: 'image/jpeg', lastModified: Date.now() })
				}
			}
			canvas.width = canvas.height = 0 // lepas memori canvas lebih cepat di WebView
			if (!maxBytes) break
			skala *= 0.75
		}
		return masuk ? file : null
	} finally {
		URL.revokeObjectURL(url)
	}
}
